import{_ as r}from"./chunks/11.D0JcP_zY.js";import{_ as o}from"./chunks/image3.DoZHhKNh.js";import{_ as n}from"./chunks/image2.BXX0Pzxx.js";import{_ as s,a as l}from"./chunks/image.k-csJPe8.js";import{_ as d}from"./chunks/image9.DCHvWr-H.js";import{_ as c}from"./chunks/image.mtVmn3vQ.js";import{_ as g}from"./chunks/image1.CcZc1vrM.js";import{_ as h}from"./chunks/image.W_Wbo9Z-.js";import{_ as p}from"./chunks/image8.2GLaHkOt.js";import{_ as m}from"./chunks/image.BZc8PBVN.js";import{_ as u}from"./chunks/100.DC6t8P7m.js";import{_ as b}from"./chunks/community.CGfILmM2.js";import{_ as f,C as v,o as w,c as y,ak as t,E as x}from"./chunks/framework.CaWw1yIg.js";const A="/projects/AiBlock/en/standard-kit/assets/1.Cl_DnHVJ.webp",_="data:image/png;base64,",a="/projects/AiBlock/en/standard-kit/assets/image.CeH_kKhq.webp",q="/projects/AiBlock/en/standard-kit/assets/image3.BVup-3Om.webp",k="/projects/AiBlock/en/standard-kit/assets/4.TGyaepgd.webp",P="/projects/AiBlock/en/standard-kit/assets/2.D06On7LG.webp",F=JSON.parse('{"title":"3.11 Geared Mixer","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Creative Builds/3.11 Geared Mixer.md","filePath":"docs/3. Creative Builds/3.11 Geared Mixer.md"}'),S={name:"docs/3. Creative Builds/3.11 Geared Mixer.md"};function T(C,e,E,z,I,j){const i=v("Pdf");return w(),y("div",null,[e[0]||(e[0]=t('<h1 id="_3-11-geared-mixer" tabindex="-1">3.11 Geared Mixer <a class="header-anchor" href="#_3-11-geared-mixer" aria-label="Permalink to &quot;3.11 Geared Mixer&quot;">​</a></h1><h2 id="_3-11-1-lesson-introduction" tabindex="-1">3.11.1 Lesson Introduction <a class="header-anchor" href="#_3-11-1-lesson-introduction" aria-label="Permalink to &quot;3.11.1 Lesson Introduction&quot;">​</a></h2><p>Taking inspiration from everyday kitchen appliances, this lesson guides the assembly of a motor-driven geared mixer. The lesson introduces the structure and transmission characteristics of vertical bevel gears, teaches variable programming alongside dual-input control logic using a knob and buttons, and achieves versatile mixing actions through motor forward and reverse speed control. This lesson advances gear transmission knowledge, reinforces variable-based state control, and builds a solid foundation across mechanical engineering and software programming for sophisticated robotics projects.</p><img loading="lazy" height="1662" width="1662" src="'+r+'" class="common_img" style="width:400px;"><h2 id="_3-11-2-learning-objectives" tabindex="-1">3.11.2 Learning Objectives <a class="header-anchor" href="#_3-11-2-learning-objectives" aria-label="Permalink to &quot;3.11.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand the structural characteristics and direction-changing principles of perpendicular bevel gear meshing. Master methods for defining, assigning, and retrieving variables. Consolidate programming concepts for motor control and sensor data acquisition.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the geared mixer and properly align the gear meshing independently. Add the knob module extension library. Create variables to manage program states. Implement integrated programming that combines knob-based speed regulation with button-controlled direction switching.</p></li><li><p><strong>Thinking Objectives</strong>: Cultivate mechanical engineering thinking regarding mechanical power redirection. Develop programming thinking centered on variable-based state control. Understand analog control logic where sensor data directly drives actuators. Strengthen multi-input decision-making capabilities.</p></li><li><p><strong>Application Objectives</strong>: Connect concepts to everyday appliances such as egg beaters, meat grinders, and automotive differentials. Recognize the universal importance of variables in computer programming. Stimulate enduring curiosity toward mechanical transmission and software design.</p></li></ol><h2 id="_3-11-3-preparation" tabindex="-1">3.11.3 Preparation <a class="header-anchor" href="#_3-11-3-preparation" aria-label="Permalink to &quot;3.11.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>360° block motor</p></li><li><p>Knob module</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab Graphical Programming Platform</li></ul><h2 id="_3-11-4-hands-on-project" tabindex="-1">3.11.4 Hands-On Project <a class="header-anchor" href="#_3-11-4-hands-on-project" aria-label="Permalink to &quot;3.11.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the variable-speed geared mixer, which utilizes perpendicular bevel gears to redirect horizontal motor rotation into vertical motion, replicating the mechanism of an electric egg beater. On the programming side, a variable is introduced to store direction states, where 0 indicates stop, positive values represent forward rotation, and negative values designate reverse rotation. Short-pressing the left or right buttons assigns the variable to -1 or 1 respectively. The main loop reads this variable to direct motor rotation, while analog values from the knob, ranging from 0 to 100, directly set the motor speed percentage. This architecture coordinates dual inputs for knob speed regulation and button direction switching. The variable acts as a status messenger, passing button trigger states into the continuous main execution loop.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),x(i,{src:"../../_static/shared/pdf/chapter_3/11.pdf"}),e[1]||(e[1]=t('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 360° block motor to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the knob module to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1367" width="1715" src="'+A+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Knob</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+o+'" class="common_img" style="width:800px;"><ul><li>Select <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+n+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="257" width="228" src="'+s+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="108" src="'+l+'"></td><td style="text-align:left;">Compares two values and returns a true or false result</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="43" width="168" src="'+_+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="108" src="'+a+'"></td><td style="text-align:left;">Retrieves the numerical value stored in the specified variable</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="58" width="264" src="'+q+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="108" src="'+a+'"></td><td style="text-align:left;">Assigns the specified variable to a designated numerical value</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="193" width="589" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+c+'"></td><td style="text-align:left;">Triggers corresponding blocks when the button is short-pressed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="148" width="624" src="'+g+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+h+'"></td><td style="text-align:left;">Sets the operating speed and rotation direction of the designated motor</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="48" width="424" src="'+p+'"></td><td style="text-align:center;"><img loading="lazy" height="80" width="99" src="'+m+'"></td><td style="text-align:left;">Reads the analog value of the knob module on the specified port</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="651" width="430" src="'+k+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><ol><li><p>Upon power-on, the variable direction control is initialized to 0. Short-pressing the left button sets direction control to -1, and short-pressing the right button sets direction control to 1.</p></li><li><p>The main program executes a continuous loop to evaluate the variable value:</p><ul><li><p>When direction control is greater than 0, motor S1 rotates forward at a speed matching the analog value of the knob on port A.</p></li><li><p>When direction control is less than 0, motor S1 rotates in reverse at a speed matching the analog value of the knob on port A.</p></li><li><p>When the variable is 0, the motor remains stationary.</p></li></ul></li></ol></li></ul><img loading="lazy" height="528" width="683" src="'+P+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to upload the program to the controller and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+u+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1xyD_-3msc3KcaGQHLqkcPOZNSNXFIirT?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-11-5-expansion-and-challenge" tabindex="-1">3.11.5 Expansion and Challenge <a class="header-anchor" href="#_3-11-5-expansion-and-challenge" aria-label="Permalink to &quot;3.11.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Timed Automated Mixer</strong></p><p>Integrate a timer routine: pressing the start button initiates automated mixing for 30 s before shutting down, simulating commercial food mixer timer functions. Utilize a variable to track remaining time, decrementing the value by 1 each second, and setting the direction variable to 0 when the countdown reaches zero. Practice variable countdown logic and timed execution control to create a smarter, realistic appliance model.</p><p><strong>Project 2: Multi-Speed Preset Mixer</strong></p><p>Implement three fixed speed presets: low speed at 30%, medium speed at 60%, and high speed at 100%. Use button presses to cycle sequentially through presets while updating RGB light colors to indicate the active tier, such as green for low, yellow for medium, and red for high. Practice variable-driven state recording, cyclic toggle logic, and multi-actuator coordination to build a versatile multi-speed mixer.</p><h2 id="_3-11-6-q-a" tabindex="-1">3.11.6 Q&amp;A <a class="header-anchor" href="#_3-11-6-q-a" aria-label="Permalink to &quot;3.11.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: What is a variable, and why are variables essential in programming?</strong></p><p>Answer: A variable functions like a labeled storage container that holds numerical data, allowing values to be retrieved, updated, and re-evaluated dynamically during runtime. Utilizing variables provides three core engineering advantages. First, it enables <strong>state retention</strong>: for instance, the direction control variable designates 1 for forward rotation and -1 for reverse rotation, allowing different routines to share and maintain direction states across execution loops. Second, it facilitates <strong>data communication</strong>: button event handlers modify the variable value, which the continuous main loop reads to command motor motion, transferring data across independent routines. Third, it ensures <strong>maintainability</strong>: storing shared parameters in variables allows system-wide values to update instantly from a single assignment point. Variables serve as fundamental building blocks in software design, underpinning nearly all complex robotics logic.</p><p><strong>Question 2: How does the knob module regulate motor speed, and why can its output value be applied directly to the motor speed parameter?</strong></p><p>Answer: The knob module outputs an analog reading ranging precisely from 0 to 100, which aligns perfectly with the motor speed input parameter of 0% to 100%. Because these numeric ranges correspond identically, the block representing the analog value of the knob on port A can be placed directly into the motor speed input slot. Turning the knob adjusts a numerical value from 0 to 100, which translates proportionally to the motor duty cycle percentage. This technique represents direct analog mapping control, where raw sensor output feeds directly into an actuator parameter. When sensor ranges and actuator parameters diverge, mathematical scaling or mapping functions become necessary, but identical ranges allow direct assignment without intermediate calculations.</p><h2 id="_3-11-7-technical-support-and-product-discussion" tabindex="-1">3.11.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-11-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.11.7 Technical Support and Product Discussion&quot;">​</a></h2><p>To share creative ideas and projects after exploring this kit, visit the Hiwonder Community:</p><a href="https://forum.hiwonder.com/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+b+'" class="common_img" style="width:800px;"></a>',31))])}const V=f(S,[["render",T]]);export{F as __pageData,V as default};
